INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1460620-me480', 'stk-user9670', 'ME 480', 'info', '{"desc": "السلام عليكم ياشباب\n\nاليوم تواصلت مع الدكتور خالد مزغاني وقالي ان مادة “ME 480 Plastics Materials and Processing” ماراح تعرض في ترم 162.\n\nيقول اذا جبت له 10 تواقيع من طلاب لهم رغبة ينزلونها الترم الجاي راح يكلم التشيرمان وينزلها ان شاء الله.\n\nطبعاً انا شخصيا أشوف المادة هذي مهمة خصوصا لو لك رغبة تشتغل في شركة لها علاقة بصناعة البوليمارات أو الأنابيب أو أي شي له علاقة بالبلاستيك ( زي سابك وغيرها ).\n\nفاللي عنده رغبه أو يعرف احد مهتم, ياليت يتواصل معي علشان اقدر اجمع التوقيعات المطلوبة وينزل الكورس باذن الله.\n\nEmail: s201226100@kfupm.edu.sa\nor: m3ath1415@gmail.com\n\nشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/plastics-materials-and-processing-162/175098/1", "user": "user9670", "ts": 1476976848000, "tid": 175098, "pn": 1}}', 1476976848000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
